<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Conscription\ExaminationManifestationAssemblyService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:conscription:assemble-examination-manifestation',description:'Assemble and deliver one examination-only Manifestation')]
final class ConscriptionAssembleExaminationManifestationCommand extends Command{public function __construct(private readonly ExaminationManifestationAssemblyService $service){parent::__construct();}protected function configure():void{$this->addArgument('authorization-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface $i,OutputInterface $o):int{try{$r=$this->service->assemble((string)$i->getArgument('authorization-id'));}catch(\Throwable $e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}if((bool)$i->getOption('json')){$o->writeln(json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));return self::SUCCESS;}$o->writeln('<info>EXAMINATION_MANIFESTATION_ASSEMBLED</info> '.$r['manifestation']['manifestation_id']);$o->writeln('Status: '.$r['status']);return self::SUCCESS;}}
